# Shared production admission predicate. Scheduler & controls dot-source this exact file.
function Assert-Sr0R12Admission {
 param([Parameter(Mandatory)][object]$Admission,[Parameter(Mandatory)][object]$Requested)
 function Fail([string]$m){throw "r12 admission rejected: $m"}
 function Same([object]$a,[object]$b,[string]$name){
  $aa=@($a);$bb=@($b)
  $aArray=($a -is [System.Collections.IEnumerable] -and $a -isnot [string]);$bArray=($b -is [System.Collections.IEnumerable] -and $b -isnot [string])
  if($aArray -or $bArray){if(-not($aArray -and $bArray)){Fail "$name array/scalar drift"};if($aa.Count -ne $bb.Count){Fail "$name length drift"};for($i=0;$i -lt $aa.Count;$i++){if([string]$aa[$i] -cne [string]$bb[$i]){Fail "$name[$i] drift"}}}elseif([string]$a -cne [string]$b){Fail "$name drift"}
 }
 foreach($key in @('schema','taskName','tag','base','controlRoot','controlReceiptRoot','runRoot','resultFile','memoryReceiptPath','startReceiptPath','coordinatorOutputPath','launcherReceiptPath','lockPath','workloadExe','rendererDll','presentMonExe','sourceRowsPath','frozenTaskPath','drainTaskPath','helperPath','drainHelperPath','parserPath','identityHelperPath','launcherHelperPath','collectorPath','coordinatorPath','workerPath','wrapperPath','admissionHelperPath','workloadExeSha256','rendererDllSha256','presentMonSha256','frozenTaskSha256','drainTaskSha256','helperSha256','drainHelperSha256','parserSha256','identityHelperSha256','launcherHelperSha256','workerSha256','collectorSha256','coordinatorSha256','wrapperSha256','admissionHelperSha256')){if($null -eq $Admission.PSObject.Properties[$key] -or $null -eq $Requested.PSObject.Properties[$key]){Fail "missing field $key"};Same $Admission.$key $Requested.$key $key}
 foreach($key in @('requiredControlReceipts')){Same $Admission.$key $Requested.$key $key}
 Same $Admission.noActivate $Requested.noActivate 'noActivate';Same $Admission.noResources $Requested.noResources 'noResources';Same $Admission.killOnJobClose $Requested.killOnJobClose 'killOnJobClose';Same $Admission.runs $Requested.runs 'runs';Same $Admission.warmup $Requested.warmup 'warmup';Same $Admission.measure $Requested.measure 'measure';Same $Admission.rows $Requested.rows 'rows';Same $Admission.keyRate $Requested.keyRate 'keyRate';Same $Admission.deadlineSeconds $Requested.deadlineSeconds 'deadlineSeconds';Same $Admission.pollSeconds $Requested.pollSeconds 'pollSeconds';Same $Admission.aggregateJobMemoryLimitBytes $Requested.aggregateJobMemoryLimitBytes 'aggregateJobMemoryLimitBytes';Same $Admission.aggregateLimitFlags $Requested.aggregateLimitFlags 'aggregateLimitFlags'
 if([string]$Admission.schema -ne 'sr0-display-selfjob-v5-one-shot-admission-r12'){Fail 'schema'};if([string]$Admission.taskName -cne [string]$Admission.tag){Fail 'task/tag owner'};if([bool]$Admission.noActivate -ne $true -or [bool]$Admission.noResources -ne $true){Fail 'interaction guard'};if([bool]$Admission.killOnJobClose -ne $false){Fail 'kill-on-close'};if([int]$Admission.runs -ne 1 -or [int]$Admission.warmup -ne 10 -or [int]$Admission.measure -ne 60 -or [int]$Admission.rows -ne 200 -or [double]$Admission.keyRate -ne 10){Fail 'workload bounds'};if([int]$Admission.deadlineSeconds -ne 900 -or [int]$Admission.pollSeconds -ne 1){Fail 'deadline/poll'};if([int64]$Admission.aggregateJobMemoryLimitBytes -ne 1073741824 -or [int]$Admission.aggregateLimitFlags -ne 512){Fail 'memory policy'}
 foreach($key in @('workloadExeSha256','rendererDllSha256','presentMonSha256','frozenTaskSha256','drainTaskSha256','helperSha256','drainHelperSha256','parserSha256','identityHelperSha256','launcherHelperSha256','workerSha256','collectorSha256','coordinatorSha256','wrapperSha256','admissionHelperSha256')){if(([string]$Admission.$key) -notmatch '^[0-9a-fA-F]{64}$'){Fail "$key hash"}}
 return $true
}
